<template>
    <div class="goods-type-wrapper">
      <div class="type-list" v-if="confirmType == 'send'">
        <div class="item" :class="{'active': selectIndex === index}"  @click="selectType(index)" v-for="(item, index) in typeList" :key="index">{{item}}</div>
      </div>
      <div class="weight-box">
        <div>重量</div>
        <div class="select-num">
          <span v-if="rangeValue < minValue">小于{{minValue}}公斤</span>
          <span v-else>{{rangeValue}}公斤</span>
        </div>
        <div class="range-box">
          <mt-range class="range" v-model="rangeValue" :min="minValue - 1" :max="maxValue"></mt-range>
          <div class="tip-box">
            <span class="tip left">小于{{minValue}}公斤</span>
            <span class="tip right">{{maxValue}}公斤</span>
          </div>
        </div>
      </div>
      <div class="btn-box"><button class="btn" @click="confirm">确定</button></div>
    </div>
</template>

<script>
export default {
  name: 'SelectGoods',
  data () {
    return {
      typeList: ['鲜花', '餐饮', '生鲜', '文件', '电子产品', '钥匙', '服饰', '其他'],
      selectIndex: -1,
      rangeValue: 2,
      minValue: 2,
      maxValue: 20,
      confirmType: 'send'
    }
  },
  created () {
    var _this = this
    this.confirmType = this.$globalData.confirmType
    if (this.confirmType == 'send') {
      var sendGoods = this.$globalData.sendGoods
      console.log('1111111111111', sendGoods)
      if (sendGoods != '') {
        this.typeList.map((item, index) => {
          if (item == sendGoods.type) {
            _this.selectIndex = index
          }
        })
        this.rangeValue = sendGoods.weight
      }
      this.getweightInfo(3)
    } else {
      let buyGoods = this.$globalData.buyGoodsWeight
      if (buyGoods != '') {
        this.rangeValue = buyGoods.weight
      }
      this.getweightInfo(2)
    }
  },
  methods: {
    selectType (index) {
      this.selectIndex = index
    },

    confirm () {
      let weight = this.rangeValue < this.minValue ? '小于' + this.minValue : this.rangeValue
      if (this.confirmType == 'send' && this.selectIndex > 0) {
        let goods = this.typeList[this.selectIndex]
        this.$globalData.sendGoods = {
          type: goods,
          weight: this.rangeValue,
          showTxt: goods + '、' + weight + '公斤'
        }
      } else if (this.confirmType == 'buy') {
        this.$globalData.buyGoodsWeight = {
          weight: this.rangeValue,
          showTxt: weight + '公斤'
        }
      }
      this.$router.back()
    },

    async getweightInfo (type) {
      try {
        let res = await this.$api.getWeightInfo({ type })
        console.log('555555555555', res)
        if (res.errorMsg) {
          return
        }
        let length = res.service_weight_info.length
        if (res.service_weight_multilevel_switch == 1 && length > 0) {
          this.minValue = res.service_weight_info[0].end_weight * 1
          if (res.service_weight_info.length > 1) {
            this.maxValue = res.service_weight_info[length - 1].end_weight * 1
          }
        }
      } catch (e) {
        console.log('获取重量信息错误 getweightInfo', e)
      }
    }
  }
}
</script>

<style lang="stylus">
.goods-type-wrapper
  height 100%
  background #fff
  .type-list
    padding 30px 0 15px 15px
    flexbox()
    flex-wrap wrap
    border-bottom 1PX solid #e5e5e5
    .item
      width -webkit-calc(25% - 15px)
      width calc(25% - 15px)
      margin-right 15px
      margin-bottom 15px
      font-size 14px
      border 1PX solid #e5e5e5
      box-sizing border-box
      padding 9px 0
      text-align center
      &.active
        border-color $color-main
        color $color-main
        background rgba($color-main, 0.1)
  .weight-box
    padding 30px 15px 0
    text-align center
    font-size 16px
    .select-num
      color $color-main
      margin-top 20px
    .range-box
      padding 0 25px
      position relative
      .range
        padding 10px 15px
        .mt-range-progress
          background $color-main
      .tip-box
        flexbox()
        justify-content space-between
        font-size 14px
  .btn-box
    padding 35px 15px 0
    .btn
      width 100%
      color #fff
      background $color-main
      font-size 17px
      line-height 2.56
      border-radius 2px
      &:active
        background darken($color-main, 10%)
</style>
